import sys

def main():
    # Read X from standard input
    # sys.stdin.read() reads the whole input, split() handles whitespace
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    X = int(input_data[0])

    total_sum = 0
    # The grid is 9x9, indexed from 1 to 9
    for i in range(1, 10):
        for j in range(1, 10):
            cell_value = i * j
            if cell_value != X:
                total_sum += cell_value

    print(total_sum)

if __name__ == "__main__":
    main()

import sys

def solve():
    # Reading input using sys.stdin.read().split() handles whitespace (spaces, newlines) automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    # Parse N and D
    try:
        N = int(next(iterator))
        D = int(next(iterator))
    except StopIteration:
        return

    # Parse the snakes' properties
    snakes = []
    for _ in range(N):
        try:
            T = int(next(iterator))
            L = int(next(iterator))
            snakes.append((T, L))
        except StopIteration:
            break

    # Process each k from 1 to D
    for k in range(1, D + 1):
        max_weight = 0
        for T, L in snakes:
            # Calculate weight: thickness * (length + k)
            current_weight = T * (L + k)
            if current_weight > max_weight:
                max_weight = current_weight
        print(max_weight)

if __name__ == '__main__':
    solve()

import sys

def main():
    # Read all input from stdin
    input_content = sys.stdin.read().split()

    if not input_content:
        return

    iterator = iter(input_content)

    try:
        # N: Number of snakes, D: Maximum increase factor
        N = int(next(iterator))
        D = int(next(iterator))

        snakes = []
        for _ in range(N):
            t = int(next(iterator))
            l = int(next(iterator))
            snakes.append((t, l))

        # Loop through each k from 1 to D
        for k in range(1, D + 1):
            max_weight = 0
            for t, l in snakes:
                # Weight is thickness * (initial_length + k)
                weight = t * (l + k)
                if weight > max_weight:
                    max_weight = weight
            print(max_weight)

    except StopIteration:
        pass

if __name__ == '__main__':
    main()

import sys

def main():
    # Read all input from standard input at once
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Read N and D
        N = int(next(iterator))
        D = int(next(iterator))

        # Read the N snakes' properties
        snakes = []
        for _ in range(N):
            T = int(next(iterator))
            L = int(next(iterator))
            snakes.append((T, L))

        # Process each k from 1 to D
        for k in range(1, D + 1):
            max_weight = 0
            # Calculate weight for each snake with increased length
            for T, L in snakes:
                weight = T * (L + k)
                if weight > max_weight:
                    max_weight = weight
            print(max_weight)

    except StopIteration:
        pass

if __name__ == '__main__':
    main()
